    <h1>User Input Form</h1>

    <form id="userForm">
        <div class="form-group">
            <label for="name">Name:</label>
            <input type="text" id="name" name="name" required>
        </div>

        <div class="form-group">
            <label for="email">Email:</label>
            <input type="text" id="email" name="email" required>
        </div>

        <div class="form-group">
            <label for="message">Message:</label>
            <textarea id="message" name="message" required></textarea>
        </div>

        <button type="submit">Save</button>
        <button type="button" class="secondary" onclick="loadSavedData()">View Saved Data</button>
        <button type="button" class="secondary" onclick="clearData()">Clear Saved Data</button>

        <div class="success-message" id="successMessage">Data saved successfully!</div>
