            successMessage.style.display = 'block';
            setTimeout(() => {
                successMessage.style.display = 'none';
            }, 3000);
        });

        // Load and display saved data
        function loadSavedData() {
            const savedData = localStorage.getItem('formData');

            if (savedData) {
                const data = JSON.parse(savedData);
                savedDataContent.innerHTML = `
                    <p><strong>Name:</strong> ${data.name}</p>
                    <p><strong>Email:</strong> ${data.email}</p>
                    <p><strong>Message:</strong> ${data.message}</p>
                    <p><strong>Saved at:</strong> ${new Date(data.timestamp).toLocaleString()}</p>
                `;
                savedDataDisplay.style.display = 'block';
            } else {
                savedDataContent.innerHTML = '<p>No saved data found.</p>';
                savedDataDisplay.style.display = 'block';
            }
        }

        // Clear saved data
        function clearData() {
            localStorage.removeItem('formData');
            form.reset();
            savedDataDisplay.style.display = 'none';
            alert('Saved data cleared!');
        }
    </script>
</body>
</html>
